  "partner.core.native.noteTitle": "పేషెంట్ పనుల కోసం వెబ్ కన్సోల్ వాడండి",
  "partner.core.native.noteBody": "పేషెంట్ రికార్డులు యాప్‌లో అందుబాటులో లేవు. ప్రిస్క్రిప్షన్లు, రిపోర్ట్ రివ్యూలు, ఎన్‌కౌంటర్ నోట్స్, మీ అపాయింట్‌మెంట్లు వెబ్‌లోని Studentkare క్లినిషియన్ కన్సోల్‌లో ఉంటాయి.",
  "partner.core.native.item": "యాప్‌లో మీరు మీ నోటిఫికేషన్లు చదవవచ్చు.",
  "partner.core.soap.eyebrow": "కన్సల్టేషన్ గది",
  "partner.core.soap.title": "కన్సల్టేషన్ నోట్స్ (SOAP)",
