  "partner.core.soap.noConsult": "ఏ కన్సల్టేషన్ జరగడం లేదు",
  "partner.core.soap.videoUnavailable": "వీడియో కాల్స్, వాయిస్ స్క్రైబ్ ఇంకా కనెక్ట్ కాలేదు. ఏదీ రికార్డ్ లేదా ట్రాన్స్‌క్రైబ్ కావడం లేదు.",
  "partner.core.soap.notSaved": "ఇక్కడ టైప్ చేసిన నోట్స్ సేవ్ కావు. నోట్ ఉంచుకోవాలంటే, దాన్ని ఎన్‌కౌంటర్ నోట్స్‌లో రాయండి.",
